-- =====================================================
-- CRM SALES INTELLIGENCE SEMANTIC VIEW REBUILD
-- WITH NEW GAME_ATTENDANCE TABLE
-- Created: March 13, 2026
-- =====================================================
-- NOTE: After running this, re-add your named filter:
-- CURRENT_RECORDS_ONLY on OPPORTUNITIES (SYSTEM_CURRENT_FLAG = 'Y')
-- =====================================================

-- Dedup view for V_ODS_SALESFORCE_TASK (unchanged)
CREATE OR REPLACE VIEW TBRDP_DW_PROD.IM_RPT.V_SALESFORCE_TASKS_CURRENT AS
SELECT *
FROM TBRDP_DW_PROD.IM_RPT.V_ODS_SALESFORCE_TASK
WHERE SYSTEM_CURRENT_FLAG = 'Y'
  AND IS_DELETED = FALSE
QUALIFY ROW_NUMBER() OVER (PARTITION BY ID ORDER BY SYSTEM_VERSION DESC) = 1;

CREATE OR REPLACE SEMANTIC VIEW TBRDP_DW_PROD.IM_RPT.SV_CRM_SALES_INTELLIGENCE
  tables (
    OPPORTUNITIES as TBRDP_DW_PROD.IM_RPT.V_ODS_SALESFORCE_OPPORTUNITY primary key (ID) with synonyms=('deals','pipeline','sales opportunities') comment='Sales opportunities with revenue, stage, and close dates',
    DEAL_HEALTH as TBRDP_DW_PROD.IM_RPT.T_DEAL_HEALTH_SCORE primary key (OPPORTUNITY_ID) with synonyms=('health scores','deal assessment') comment='AI-generated health scores and risk assessments for opportunities',
    ACTIVITY_METRICS as TBRDP_DW_PROD.IM_RPT.T_OPPORTUNITY_ACTIVITY_METRICS primary key (OPPORTUNITY_ID) with synonyms=('engagement','activities','interactions') comment='Aggregated email, call, and task metrics per opportunity',
    USERS as TBRDP_DW_PROD.IM_RPT.V_ODS_SALESFORCE_USER primary key (ID) with synonyms=('sales reps','account executives','owners') comment='Sales representative details and team information',
    TICKET_TEAM_DEPT as TBRDP_DW_PROD.IM_RPT.T_TICKET_TEAM_DEPARTMENT_MAPPING primary key (USER_ID) with synonyms=('ticket team','department classification','sales vs service','group AEs','SM AEs','TSRs','corporate partnerships') comment='Department classification for 23 reps across 5 teams',
    CUSTOMER_360 as TBRDP_DW_PROD.IM_RPT.T_CUSTOMER_360 primary key (SF_ACCOUNT_ID) with synonyms=('customer intelligence','customer 360','customer profile','customer data','account intelligence','lifetime value','LTV','customer lifetime') comment='Unified customer view linking CRM opportunities to actual ticket purchases',
    EMAIL_ANALYTICS as TBRDP_DW_PROD.IM_RPT.T_EMAIL_ANALYTICS primary key (EMAIL_ID) with synonyms=('emails','email activity','email metrics','email volume','outreach','communications','response times') comment='Individual email records with timestamps, direction, rep attribution, sentiment',
    SALESFORCE_TASKS as TBRDP_DW_PROD.IM_RPT.V_SALESFORCE_TASKS_CURRENT primary key (ID) with synonyms=('tasks','to-dos','follow-ups','action items','salesforce tasks','task list') comment='Individual Salesforce task records',
    CALL_ACTIVITY as TBRDP_DW_PROD.IM_RPT.T_CALL_ACTIVITY primary key (SESSION_ID) with synonyms=('call activity','call data','call log','call metrics','calls','phone activity','phone calls','zoom calls') comment='Unified call activity from Zoom Contact Center and Zoom Phone',
    GAME_ATTENDANCE as TBRDP_DW_PROD.IM_RPT.V_CUSTOMER_GAME_ATTENDANCE primary key (FINANCIAL_PATRON_ACCOUNT_ID) with synonyms=('game attendance','attendance','games attended','win loss','game results','rays wins','rays losses','fan attendance') comment='Game attendance metrics linked to MLB game results. Shows games attended, win/loss record at attended games, ticket spend, and seasons attended. Links to CUSTOMER_360 via patron account ID.'
  )
  relationships (
    OPPORTUNITIES_TO_ACTIVITY as OPPORTUNITIES(ID) references ACTIVITY_METRICS(OPPORTUNITY_ID),
    OPPORTUNITIES_TO_CUSTOMER as OPPORTUNITIES(ACCOUNT_ID) references CUSTOMER_360(SF_ACCOUNT_ID),
    OPPORTUNITIES_TO_HEALTH as OPPORTUNITIES(ID) references DEAL_HEALTH(OPPORTUNITY_ID),
    OPPORTUNITIES_TO_OWNER as OPPORTUNITIES(OWNER_ID) references USERS(ID),
    USERS_TO_TICKET_DEPT as USERS(ID) references TICKET_TEAM_DEPT(USER_ID),
    EMAILS_TO_OPPORTUNITY as EMAIL_ANALYTICS(OPPORTUNITY_ID) references OPPORTUNITIES(ID),
    EMAILS_TO_REP as EMAIL_ANALYTICS(REP_USER_ID) references USERS(ID),
    TASKS_TO_OPPORTUNITY as SALESFORCE_TASKS(WHAT_ID) references OPPORTUNITIES(ID),
    TASKS_TO_OWNER as SALESFORCE_TASKS(OWNER_ID) references USERS(ID),
    CALL_TO_OPPORTUNITY as CALL_ACTIVITY(OPPORTUNITY_ID) references OPPORTUNITIES(ID),
    CALL_TO_USER as CALL_ACTIVITY(AGENT_OWNER_ID) references USERS(ID),
    CUSTOMER_TO_GAME_ATTENDANCE as CUSTOMER_360(PATRON_ACCOUNT_ID) references GAME_ATTENDANCE(FINANCIAL_PATRON_ACCOUNT_ID)
  )
  facts (
    OPPORTUNITIES.DEAL_AMOUNT as opportunities.AMOUNT comment='Revenue amount of the opportunity',
    OPPORTUNITIES.WEIGHTED_AMOUNT as opportunities.AMOUNT * (opportunities.PROBABILITY / 100) comment='Probability-weighted revenue',
    OPPORTUNITIES.PROBABILITY_PCT as opportunities.PROBABILITY comment='Win probability percentage (0-100)',
    DEAL_HEALTH.HEALTH_SCORE_VALUE as deal_health.HEALTH_SCORE comment='AI-calculated health score (0-100)',
    ACTIVITY_METRICS.TOTAL_EMAILS_COUNT as activity_metrics.TOTAL_EMAILS comment='Total email count for this opportunity',
    ACTIVITY_METRICS.TOTAL_CALLS_COUNT as activity_metrics.TOTAL_CALLS comment='Total call count for this opportunity',
    ACTIVITY_METRICS.DAYS_SINCE_CONTACT as activity_metrics.DAYS_SINCE_LAST_EMAIL comment='Days since last email contact',
    ACTIVITY_METRICS.AVG_SENTIMENT_SCORE as activity_metrics.AVG_EMAIL_SENTIMENT comment='Average email sentiment score (-1 to 1)',
    CUSTOMER_360.CUST_TICKET_REV as customer_360.TOTAL_TICKET_REVENUE comment='Total ticket purchase revenue for this customer',
    CUSTOMER_360.CUST_CRM_WON_REV as customer_360.CRM_WON_REVENUE comment='Total CRM opportunity won revenue',
    CUSTOMER_360.CUST_LTV as customer_360.ESTIMATED_LIFETIME_VALUE comment='Estimated customer lifetime value',
    CUSTOMER_360.CUST_PURCHASE_COUNT as customer_360.TOTAL_TICKET_PURCHASES comment='Total ticket transactions',
    CUSTOMER_360.CUST_OPP_COUNT as customer_360.TOTAL_OPPORTUNITIES comment='Total CRM opportunities',
    CUSTOMER_360.CUST_WON_OPP_COUNT as customer_360.WON_OPPORTUNITIES comment='Total won CRM opportunities',
    CUSTOMER_360.CUST_DAYS_SINCE_PURCHASE as customer_360.DAYS_SINCE_LAST_PURCHASE comment='Days since last ticket purchase',
    CUSTOMER_360.CUST_EVENTS_ATTENDED as customer_360.UNIQUE_EVENTS_ATTENDED comment='Number of unique events attended',
    CUSTOMER_360.CUST_SEASON_TIX_REV as customer_360.SEASON_TICKET_REVENUE comment='Revenue from Traditional Season tickets',
    CUSTOMER_360.CUST_SINGLE_GAME_REV as customer_360.SINGLE_GAME_REVENUE comment='Revenue from Single Game tickets',
    CUSTOMER_360.CUST_SUITE_REV as customer_360.SUITE_REVENUE comment='Revenue from Suite tickets',
    CUSTOMER_360.CUST_GROUP_REV as customer_360.GROUP_REVENUE comment='Revenue from Group tickets',
    CUSTOMER_360.CUST_FLEX_REV as customer_360.FLEX_SEASON_REVENUE comment='Revenue from Flex Season tickets',
    CUSTOMER_360.CUST_SPONSOR_REV as customer_360.SPONSOR_REVENUE comment='Revenue from Sponsor tickets',
    CUSTOMER_360.CUST_CONVERSION_DAYS as customer_360.DAYS_OPP_TO_FIRST_PURCHASE comment='Days from first CRM opportunity to first purchase',
    CUSTOMER_360.CUST_SEASONS_COUNT as customer_360.SEASONS_PURCHASED comment='Number of different seasons purchased',
    EMAIL_ANALYTICS.EMAIL_SENTIMENT as email_analytics.SENTIMENT_SCORE comment='Sentiment score for this email (-1 to 1)',
    EMAIL_ANALYTICS.EMAIL_RESPONSE_MINUTES as email_analytics.RESPONSE_MINUTES comment='Minutes until first inbound response',
    CALL_ACTIVITY.TALK_TIME_SECONDS as TALK_TIME_SECONDS with synonyms=('talk time','speaking time','conversation time') comment='Actual talk time in seconds',
    CALL_ACTIVITY.DURATION_SECONDS as DURATION_SECONDS with synonyms=('call length','total duration') comment='Total call duration in seconds',
    GAME_ATTENDANCE.GAMES_ATTENDED_COUNT as game_attendance.GAMES_ATTENDED with synonyms=('games attended','attendance count','number of games') comment='Total number of games attended by this customer',
    GAME_ATTENDANCE.WINS_ATTENDED as game_attendance.GAMES_WON with synonyms=('wins attended','rays wins attended','games won') comment='Number of Rays wins at games attended by this customer',
    GAME_ATTENDANCE.LOSSES_ATTENDED as game_attendance.GAMES_LOST with synonyms=('losses attended','rays losses attended','games lost') comment='Number of Rays losses at games attended by this customer',
    GAME_ATTENDANCE.WIN_PERCENTAGE_ATTENDED as game_attendance.WIN_PCT_ATTENDED with synonyms=('win rate attended','win percentage at attended games','luck factor') comment='Percentage of attended games that were Rays wins',
    GAME_ATTENDANCE.TOTAL_TICKET_SPEND_AMOUNT as game_attendance.TOTAL_TICKET_SPEND with synonyms=('ticket spending','total spend') comment='Total amount spent on tickets for attended games',
    GAME_ATTENDANCE.AVG_TICKET_PRICE_AMOUNT as game_attendance.AVG_TICKET_PRICE with synonyms=('average ticket price','avg price') comment='Average ticket price for attended games'
  )
  dimensions (
    OPPORTUNITIES.OPP_NAME as opportunities.NAME with synonyms=('opportunity name','deal name') comment='Name of the sales opportunity',
    OPPORTUNITIES.STAGE as opportunities.STAGE_NAME with synonyms=('sales stage','pipeline stage','deal stage') comment='Current stage in the sales pipeline',
    OPPORTUNITIES.CLOSE_DATE as opportunities.CLOSE_DATE with synonyms=('expected close','close date') comment='Expected close date',
    OPPORTUNITIES.CLOSE_MONTH as DATE_TRUNC('MONTH', opportunities.CLOSE_DATE) with synonyms=('closing month') comment='Month when opportunity is expected to close',
    OPPORTUNITIES.CLOSE_QUARTER as DATE_TRUNC('QUARTER', opportunities.CLOSE_DATE) with synonyms=('closing quarter') comment='Quarter when opportunity is expected to close',
    OPPORTUNITIES.CREATED_DATE as opportunities.CREATED_DATE with synonyms=('creation date','opened date','opportunity created') comment='Date when opportunity was created',
    OPPORTUNITIES.CREATED_MONTH as DATE_TRUNC('MONTH', opportunities.CREATED_DATE) with synonyms=('creation month') comment='Month when opportunity was created',
    OPPORTUNITIES.CREATED_QUARTER as DATE_TRUNC('QUARTER', opportunities.CREATED_DATE) with synonyms=('creation quarter') comment='Quarter when opportunity was created',
    OPPORTUNITIES.IS_CLOSED as opportunities.IS_CLOSED with synonyms=('closed status') comment='Whether opportunity is closed',
    OPPORTUNITIES.IS_WON as opportunities.IS_WON with synonyms=('won status') comment='Whether opportunity was won',
    OPPORTUNITIES.PRIMARY_OBJECTION as opportunities.OBJECTIONS_C with synonyms=('objection','loss reason','why lost') comment='Primary objection or loss reason',
    OPPORTUNITIES.SECONDARY_OBJECTION as opportunities.SECONDARY_OBJECTIONS_C with synonyms=('secondary objection') comment='Secondary objection detail',
    DEAL_HEALTH.HEALTH_CATEGORY as deal_health.HEALTH_CATEGORY with synonyms=('health status','deal health','risk level') comment='Health category: Healthy, At Risk, or Critical',
    DEAL_HEALTH.IS_AT_RISK as (deal_health.HEALTH_CATEGORY IN ('At Risk', 'Critical')) with synonyms=('at risk flag') comment='Boolean flag for at-risk opportunities',
    ACTIVITY_METRICS.ENGAGEMENT_LEVEL as activity_metrics.ENGAGEMENT_LEVEL with synonyms=('activity level') comment='Engagement level: High, Medium, or Low',
    ACTIVITY_METRICS.HAS_SENTIMENT_RISK as activity_metrics.HAS_SENTIMENT_RISK with synonyms=('negative sentiment flag') comment='Whether opportunity has negative email sentiment',
    ACTIVITY_METRICS.IS_GHOSTED_FLAG as activity_metrics.IS_GHOSTED with synonyms=('ghosted status') comment='Whether opportunity has had no contact for 60+ days',
    USERS.REP_NAME as users.NAME with synonyms=('sales rep','account executive','owner name') comment='Name of the sales representative',
    USERS.REP_EMAIL as users.EMAIL with synonyms=('owner email') comment='Email address of sales rep',
    USERS.IS_ACTIVE as users.IS_ACTIVE with synonyms=('active rep') comment='Whether sales rep is active',
    TICKET_TEAM_DEPT.TICKET_DEPARTMENT as ticket_team_dept.DEPARTMENT with synonyms=('department','team type') comment='Department code',
    TICKET_TEAM_DEPT.TICKET_TEAM as ticket_team_dept.TEAM with synonyms=('team name') comment='Team display name',
    TICKET_TEAM_DEPT.TICKET_REP_NAME as ticket_team_dept.USER_NAME with synonyms=('department rep name') comment='Sales or service rep name',
    CUSTOMER_360.ACCOUNT_NAME as customer_360.SF_ACCOUNT_NAME with synonyms=('customer name','account name') comment='Salesforce account name',
    CUSTOMER_360.CUSTOMER_SEGMENT as customer_360.CUSTOMER_SEGMENT with synonyms=('customer type','segment') comment='Customer segment: CRM + Purchaser, CRM Only, Direct Purchaser, or Prospect',
    CUSTOMER_360.REVENUE_TIER as customer_360.REVENUE_TIER with synonyms=('value tier','customer tier') comment='Revenue tier: Platinum, Gold, Silver, Bronze, No Revenue',
    CUSTOMER_360.RECENCY_TIER as customer_360.RECENCY_TIER with synonyms=('recency','activity recency') comment='Recency tier: Active, Recent, Lapsed, Dormant, No Purchases',
    CUSTOMER_360.CHURN_RISK as customer_360.CHURN_RISK_FLAG with synonyms=('churn risk') comment='Whether customer is at risk of churning',
    CUSTOMER_360.UPSELL_FLAG as customer_360.UPSELL_CANDIDATE with synonyms=('upsell candidate') comment='Whether customer is an upsell candidate',
    CUSTOMER_360.LOYAL_FLAG as customer_360.IS_LOYAL_CUSTOMER with synonyms=('loyal customer','repeat buyer') comment='Whether customer has purchased 3+ seasons',
    CUSTOMER_360.HAS_BOTH as customer_360.HAS_CRM_AND_PURCHASES with synonyms=('has CRM and purchases') comment='Whether customer has both CRM opportunities AND purchases',
    CUSTOMER_360.TICKET_TYPES as customer_360.TICKET_TYPES_PURCHASED with synonyms=('ticket types bought') comment='Comma-separated list of ticket types purchased',
    CUSTOMER_360.PURCHASE_SEASON_LIST as customer_360.PURCHASE_SEASONS with synonyms=('seasons purchased') comment='Comma-separated list of seasons with purchases',
    CUSTOMER_360.PERSON_ACCOUNT as customer_360.IS_PERSON_ACCOUNT with synonyms=('person account') comment='Whether this is a person vs business account',
    CUSTOMER_360.ACCOUNT_BILLING_CITY as customer_360.BILLING_CITY with synonyms=('city') comment='Billing city',
    CUSTOMER_360.ACCOUNT_BILLING_STATE as customer_360.BILLING_STATE with synonyms=('state') comment='Billing state',
    EMAIL_ANALYTICS.EMAIL_SEND_DATE as email_analytics.EMAIL_DATE with synonyms=('email date') comment='Date the email was sent/received',
    EMAIL_ANALYTICS.EMAIL_TIMESTAMP as email_analytics.MESSAGE_DATE with synonyms=('email timestamp') comment='Exact timestamp',
    EMAIL_ANALYTICS.EMAIL_DIR as email_analytics.EMAIL_DIRECTION with synonyms=('inbound outbound') comment='Inbound or Outbound',
    EMAIL_ANALYTICS.EMAIL_DAY as email_analytics.EMAIL_DAY_NAME with synonyms=('day of week') comment='Day of week email was sent',
    EMAIL_ANALYTICS.EMAIL_HOUR_OF_DAY as email_analytics.EMAIL_HOUR with synonyms=('hour sent') comment='Hour of day (0-23)',
    EMAIL_ANALYTICS.EMAIL_TIME_BUCKET as email_analytics.TIME_OF_DAY_BUCKET with synonyms=('time of day') comment='Time of day bucket',
    EMAIL_ANALYTICS.EMAIL_RESPONSE_BUCKET as email_analytics.RESPONSE_TIME_BUCKET with synonyms=('response speed') comment='Response time category',
    EMAIL_ANALYTICS.EMAIL_REP as email_analytics.REP_NAME with synonyms=('email sender') comment='Rep associated with email',
    EMAIL_ANALYTICS.EMAIL_SENT_CATEGORY as email_analytics.SENTIMENT_CATEGORY with synonyms=('email tone') comment='Sentiment category',
    EMAIL_ANALYTICS.EMAIL_OPP_NAME as email_analytics.OPPORTUNITY_NAME with synonyms=('related opportunity') comment='Linked opportunity name',
    EMAIL_ANALYTICS.EMAIL_SUBJECT as email_analytics.SUBJECT with synonyms=('email subject') comment='Subject line',
    SALESFORCE_TASKS.TASK_SUBJECT as salesforce_tasks.SUBJECT with synonyms=('task name') comment='Task subject',
    SALESFORCE_TASKS.TASK_STATUS as salesforce_tasks.STATUS with synonyms=('task status') comment='Task status',
    SALESFORCE_TASKS.TASK_TYPE as salesforce_tasks.TYPE with synonyms=('task type') comment='Type of task',
    SALESFORCE_TASKS.TASK_PRIORITY as salesforce_tasks.PRIORITY with synonyms=('task priority') comment='Priority level',
    SALESFORCE_TASKS.TASK_DUE_DATE as salesforce_tasks.ACTIVITY_DATE with synonyms=('due date','task due date') comment='Scheduled due date',
    SALESFORCE_TASKS.TASK_IS_CLOSED as salesforce_tasks.IS_CLOSED with synonyms=('task closed') comment='Whether task is closed',
    SALESFORCE_TASKS.TASK_CALL_DISPOSITION as salesforce_tasks.CALL_DISPOSITION with synonyms=('task call outcome') comment='Call disposition',
    SALESFORCE_TASKS.TASK_DESCRIPTION as salesforce_tasks.DESCRIPTION with synonyms=('task notes') comment='Task description',
    CALL_ACTIVITY.CALL_DIRECTION as CALL_DIRECTION with synonyms=('call type','direction') comment='Inbound or Outbound',
    CALL_ACTIVITY.CALL_SOURCE as CALL_SOURCE with synonyms=('call system') comment='Source system',
    CALL_ACTIVITY.CALL_CHANNEL as CALL_CHANNEL comment='Communication channel',
    CALL_ACTIVITY.INTERACTION_TYPE as INTERACTION_TYPE with synonyms=('contact center or phone') comment='Contact Center or Phone',
    CALL_ACTIVITY.AGENT_NAME as AGENT_NAME with synonyms=('caller name') comment='Sales rep name',
    CALL_ACTIVITY.AGENT_EMAIL as AGENT_EMAIL comment='Agent email',
    CALL_ACTIVITY.AGENT_OWNER_ID as AGENT_OWNER_ID comment='Salesforce User ID',
    CALL_ACTIVITY.IS_ACTIVE_SALES_REP as IS_ACTIVE_SALES_REP with synonyms=('active sales rep') comment='Whether agent is active Ticket Sales rep',
    CALL_ACTIVITY.DISPOSITION as DISPOSITION comment='Disposition/outcome',
    CALL_ACTIVITY.CALL_RESULT as CALL_RESULT with synonyms=('call outcome') comment='Call result',
    CALL_ACTIVITY.IS_MISSED as IS_MISSED with synonyms=('missed call') comment='Whether call was missed',
    CALL_ACTIVITY.IS_TRANSFER as IS_TRANSFER comment='Whether call was transferred',
    CALL_ACTIVITY.CONSUMER_NAME as CONSUMER_NAME with synonyms=('consumer name','fan name') comment='Customer name on call',
    CALL_ACTIVITY.CONSUMER_PHONE as CONSUMER_PHONE comment='Consumer phone number',
    CALL_ACTIVITY.CONTACT_PHONE as CONTACT_PHONE comment='Contact phone number',
    CALL_ACTIVITY.CALLEE_PHONE as CALLEE_PHONE comment='Phone number called',
    CALL_ACTIVITY.CALL_NOTES as CALL_NOTES with synonyms=('call notes') comment='Notes logged by rep',
    CALL_ACTIVITY.VOICEMAIL_CONTENT as VOICEMAIL_CONTENT with synonyms=('voicemail') comment='Voicemail content',
    CALL_ACTIVITY.RECORDING_REFERENCE as RECORDING_REFERENCE comment='Recording URL',
    CALL_ACTIVITY.QUEUE_NAME as QUEUE_NAME with synonyms=('call queue') comment='Contact Center queue name',
    CALL_ACTIVITY.OPPORTUNITY_ID as OPPORTUNITY_ID comment='Linked opportunity ID',
    CALL_ACTIVITY.ACCOUNT_ID as ACCOUNT_ID comment='Linked account ID',
    CALL_ACTIVITY.CONTACT_ID as CONTACT_ID comment='Linked contact ID',
    CALL_ACTIVITY.LINKED_TASK_ID as LINKED_TASK_ID comment='Linked Salesforce Task ID',
    CALL_ACTIVITY.TASK_SUBJECT as TASK_SUBJECT comment='Linked task subject',
    CALL_ACTIVITY.TASK_NOTES as TASK_NOTES comment='Linked task notes',
    CALL_ACTIVITY.SESSION_ID as SESSION_ID comment='Unique call identifier',
    CALL_ACTIVITY.RECORD_NAME as RECORD_NAME comment='Salesforce record name',
    CALL_ACTIVITY.ENGAGEMENT_ID as ENGAGEMENT_ID comment='Zoom engagement ID',
    CALL_ACTIVITY.CHANNEL_SOURCE as CHANNEL_SOURCE comment='Channel source detail',
    CALL_ACTIVITY.CALL_START_TIME as CALL_START_TIME with synonyms=('call date','call time') comment='Call start time (Eastern)',
    CALL_ACTIVITY.CALL_END_TIME as CALL_END_TIME comment='Call end time (Eastern)',
    CALL_ACTIVITY.CALL_MONTH as DATE_TRUNC('MONTH', CALL_START_TIME) with synonyms=('call month') comment='Month of call',
    CALL_ACTIVITY.CALL_WEEK as DATE_TRUNC('WEEK', CALL_START_TIME) with synonyms=('call week') comment='Week of call',
    CALL_ACTIVITY.CALL_DATE as DATE(CALL_START_TIME) with synonyms=('date of call') comment='Date of call',
    CALL_ACTIVITY.CREATED_DATE as CREATED_DATE comment='Record creation date',
    CALL_ACTIVITY.LAST_MODIFIED_DATE as LAST_MODIFIED_DATE comment='Last modified date',
    CALL_ACTIVITY.LOADED_AT as LOADED_AT comment='When loaded into T_CALL_ACTIVITY',
    GAME_ATTENDANCE.FIRST_GAME as game_attendance.FIRST_GAME_DATE with synonyms=('first game attended','first attendance') comment='Date of first game attended',
    GAME_ATTENDANCE.LAST_GAME as game_attendance.LAST_GAME_DATE with synonyms=('last game attended','most recent game') comment='Date of most recent game attended',
    GAME_ATTENDANCE.SEASONS_ATTENDED as game_attendance.SEASONS_ATTENDED with synonyms=('seasons attended list','which seasons attended') comment='Comma-separated list of seasons attended',
    GAME_ATTENDANCE.SEASONS_COUNT as game_attendance.SEASONS_ATTENDED_COUNT with synonyms=('number of seasons attended','how many seasons') comment='Number of different seasons attended'
  )
  metrics (
    OPPORTUNITIES.TOTAL_PIPELINE_VALUE as SUM(opportunities.deal_amount) comment='Total value of all opportunities',
    OPPORTUNITIES.WEIGHTED_PIPELINE_VALUE as SUM(opportunities.weighted_amount) comment='Total probability-weighted pipeline',
    OPPORTUNITIES.AVERAGE_DEAL_SIZE as AVG(opportunities.deal_amount) comment='Average opportunity value',
    OPPORTUNITIES.OPPORTUNITY_COUNT as COUNT(opportunities.ID) comment='Total number of opportunities',
    OPPORTUNITIES.WON_COUNT as SUM(CASE WHEN opportunities.IS_WON = TRUE THEN 1 ELSE 0 END) comment='Number of won opportunities',
    OPPORTUNITIES.LOST_COUNT as SUM(CASE WHEN opportunities.IS_CLOSED = TRUE AND opportunities.IS_WON = FALSE THEN 1 ELSE 0 END) comment='Number of lost opportunities',
    OPPORTUNITIES.WIN_RATE_PCT as (SUM(CASE WHEN opportunities.IS_WON = TRUE THEN 1 ELSE 0 END) * 100.0) / NULLIF(SUM(CASE WHEN opportunities.IS_CLOSED = TRUE THEN 1 ELSE 0 END), 0) comment='Win rate percentage',
    OPPORTUNITIES.TICKET_SALES_PIPELINE as SUM(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_SALES' THEN opportunities.deal_amount ELSE 0 END) with synonyms=('group AE pipeline') comment='Total pipeline for Ticket Sales Group AEs',
    OPPORTUNITIES.TICKET_SERVICE_PIPELINE as SUM(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_SERVICE' THEN opportunities.deal_amount ELSE 0 END) with synonyms=('service pipeline') comment='Total pipeline for Ticket Service',
    OPPORTUNITIES.TICKET_SALES_COUNT as COUNT(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_SALES' THEN 1 END) with synonyms=('group AE opportunities') comment='Number of Ticket Sales opportunities',
    OPPORTUNITIES.TICKET_SERVICE_COUNT as COUNT(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_SERVICE' THEN 1 END) with synonyms=('service opportunities') comment='Number of Ticket Service opportunities',
    OPPORTUNITIES.MEMBER_AE_PIPELINE as SUM(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_MEMBER_AE' THEN opportunities.deal_amount ELSE 0 END) with synonyms=('member AE pipeline') comment='Total pipeline for Member AEs',
    OPPORTUNITIES.MEMBER_AE_COUNT as COUNT(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_MEMBER_AE' THEN 1 END) with synonyms=('member AE opportunities') comment='Number of Member AE opportunities',
    OPPORTUNITIES.TSR_PIPELINE as SUM(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_TSR' THEN opportunities.deal_amount ELSE 0 END) with synonyms=('TSR pipeline') comment='Total pipeline for TSRs',
    OPPORTUNITIES.TSR_COUNT as COUNT(CASE WHEN ticket_team_dept.ticket_department = 'TICKET_TSR' THEN 1 END) with synonyms=('TSR opportunities') comment='Number of TSR opportunities',
    OPPORTUNITIES.CP_SALES_PIPELINE as SUM(CASE WHEN ticket_team_dept.ticket_department = 'CORPORATE_PARTNERSHIP_SALES' THEN opportunities.deal_amount ELSE 0 END) with synonyms=('corporate partnership pipeline') comment='Total pipeline for CP Sales',
    OPPORTUNITIES.CP_SALES_COUNT as COUNT(CASE WHEN ticket_team_dept.ticket_department = 'CORPORATE_PARTNERSHIP_SALES' THEN 1 END) with synonyms=('CP opportunities') comment='Number of CP opportunities',
    DEAL_HEALTH.AVERAGE_HEALTH_SCORE as AVG(deal_health.health_score_value) comment='Average health score',
    DEAL_HEALTH.AT_RISK_COUNT as COUNT(CASE WHEN deal_health.is_at_risk = TRUE THEN 1 END) comment='Count of at-risk opportunities',
    DEAL_HEALTH.AT_RISK_VALUE as SUM(CASE WHEN deal_health.is_at_risk = TRUE THEN opportunities.deal_amount ELSE 0 END) comment='Pipeline value at risk',
    ACTIVITY_METRICS.TOTAL_EMAIL_VOLUME as SUM(activity_metrics.total_emails_count) comment='Total emails across opportunities',
    ACTIVITY_METRICS.TOTAL_CALL_VOLUME as SUM(activity_metrics.total_calls_count) comment='Total calls across opportunities',
    ACTIVITY_METRICS.AVG_EMAILS_PER_DEAL as AVG(activity_metrics.total_emails_count) comment='Average emails per opportunity',
    ACTIVITY_METRICS.GHOSTED_DEAL_COUNT as COUNT(CASE WHEN activity_metrics.is_ghosted_flag = TRUE THEN 1 END) comment='Opportunities with no contact 60+ days',
    CUSTOMER_360.TOTAL_CUSTOMER_VALUE as SUM(customer_360.cust_ltv) comment='Total customer lifetime value',
    CUSTOMER_360.AVG_CUSTOMER_LTV as AVG(customer_360.cust_ltv) comment='Average customer lifetime value',
    CUSTOMER_360.CUSTOMER_COUNT as COUNT(DISTINCT customer_360.SF_ACCOUNT_ID) comment='Number of unique customers',
    CUSTOMER_360.HIGH_VALUE_CUSTOMER_COUNT as COUNT(CASE WHEN customer_360.revenue_tier IN ('Platinum','Gold') THEN 1 END) comment='Number of Platinum/Gold customers',
    CUSTOMER_360.CHURN_RISK_COUNT as COUNT(CASE WHEN customer_360.churn_risk = TRUE THEN 1 END) comment='Customers at risk of churning',
    CUSTOMER_360.UPSELL_CANDIDATE_COUNT as COUNT(CASE WHEN customer_360.upsell_flag = TRUE THEN 1 END) comment='Number of upsell candidates',
    CUSTOMER_360.LOYAL_CUSTOMER_COUNT as COUNT(CASE WHEN customer_360.loyal_flag = TRUE THEN 1 END) comment='Customers with 3+ season purchases',
    EMAIL_ANALYTICS.EMAIL_COUNT as COUNT(email_analytics.EMAIL_ID) comment='Total email count',
    EMAIL_ANALYTICS.OUTBOUND_EMAIL_COUNT as COUNT(CASE WHEN email_analytics.email_dir = 'Outbound' THEN 1 END) comment='Count of outbound emails',
    EMAIL_ANALYTICS.INBOUND_EMAIL_COUNT as COUNT(CASE WHEN email_analytics.email_dir = 'Inbound' THEN 1 END) comment='Count of inbound emails',
    EMAIL_ANALYTICS.AVG_RESPONSE_TIME_MINUTES as AVG(email_analytics.email_response_minutes) comment='Average response time in minutes',
    CALL_ACTIVITY.CALL_COUNT as COUNT(call_activity.SESSION_ID) with synonyms=('total calls','number of calls') comment='Total number of calls',
    CALL_ACTIVITY.INBOUND_CALL_COUNT as COUNT(CASE WHEN call_activity.CALL_DIRECTION = 'Inbound' THEN 1 END) with synonyms=('inbound calls') comment='Number of inbound calls',
    CALL_ACTIVITY.OUTBOUND_CALL_COUNT as COUNT(CASE WHEN call_activity.CALL_DIRECTION = 'Outbound' THEN 1 END) with synonyms=('outbound calls') comment='Number of outbound calls',
    CALL_ACTIVITY.TOTAL_TALK_TIME as SUM(call_activity.TALK_TIME_SECONDS) with synonyms=('total talk time','total speaking time') comment='Total talk time in seconds',
    CALL_ACTIVITY.AVG_TALK_TIME as AVG(call_activity.TALK_TIME_SECONDS) with synonyms=('average talk time','avg call length') comment='Average talk time per call in seconds',
    CALL_ACTIVITY.MISSED_CALL_COUNT as COUNT(CASE WHEN call_activity.IS_MISSED = TRUE THEN 1 END) with synonyms=('missed calls','unanswered calls') comment='Number of missed calls',
    GAME_ATTENDANCE.TOTAL_GAMES_ATTENDED as SUM(game_attendance.GAMES_ATTENDED) with synonyms=('total games attended','total attendance') comment='Total games attended across all customers',
    GAME_ATTENDANCE.TOTAL_WINS_ATTENDED as SUM(game_attendance.GAMES_WON) with synonyms=('total wins attended','rays wins seen') comment='Total Rays wins attended across all customers',
    GAME_ATTENDANCE.TOTAL_LOSSES_ATTENDED as SUM(game_attendance.GAMES_LOST) with synonyms=('total losses attended','rays losses seen') comment='Total Rays losses attended across all customers',
    GAME_ATTENDANCE.AVG_WIN_PCT_ATTENDED as AVG(game_attendance.WIN_PCT_ATTENDED) with synonyms=('average win percentage attended','avg luck factor') comment='Average win percentage at attended games',
    GAME_ATTENDANCE.TOTAL_GAME_TICKET_SPEND as SUM(game_attendance.TOTAL_TICKET_SPEND) with synonyms=('total ticket spend on games','game spend') comment='Total ticket spend on attended games',
    GAME_ATTENDANCE.AVG_GAMES_PER_CUSTOMER as AVG(game_attendance.GAMES_ATTENDED) with synonyms=('average games attended','avg attendance') comment='Average games attended per customer',
    GAME_ATTENDANCE.CUSTOMERS_WITH_HIGH_WIN_PCT as COUNT(CASE WHEN game_attendance.WIN_PCT_ATTENDED >= 60 THEN 1 END) with synonyms=('lucky customers','high win rate fans') comment='Number of customers who attended games with 60%+ Rays wins'
  );

